// ingest-programming-brain.mjs — builds the BRAIN's "Programing_Brain" corpus from
// ../Programing_Brain/{nyelvek,temak}/*.md (format: Programing_Brain/FORMATUM.md).
// Output: src/brain/seed/programmingBrain.ingested.ts  (GENERATED — do not edit by hand)
//   PB_CHUNKS → learner.observe()       (vocabulary + associations, per tech)
//   PB_QA     → learner.observeTurn()   (question → explanation + code answers)
// Offline, no dependencies.  Usage: node scripts/ingest-programming-brain.mjs
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const SRC = resolve(HERE, '../../Programing_Brain');
const OUT = resolve(HERE, '../src/brain/seed/programmingBrain.ingested.ts');
const MAX_CHUNK = 4000; // chars per observed chunk
const MAX_ANSWER = 1200; // learner keeps ≤ 1200 chars of an answer

const meta = (s, key) => (s.match(new RegExp(`<!--\\s*${key}:\\s*(.*?)\\s*-->`)) || [])[1] || '';
const stripMeta = (s) => s.replace(/<!--[\s\S]*?-->/g, '').trim();

function splitProseCode(body) {
  const code = [];
  const prose = body.replace(/```[\w+#.-]*\n([\s\S]*?)```/g, (_, c) => (code.push(c.trimEnd()), ' ')).replace(/\s+/g, ' ').trim();
  return { prose, code };
}

function parseFile(path) {
  const text = readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
  const tech = meta(text, 'tech') || 'misc';
  const title = (text.match(/^#\s+(.+)$/m) || [])[1]?.trim() || tech;
  const parts = text.split(/^##\s+/m);
  const src = relative(resolve(SRC, '..'), path).replace(/\\/g, '/');
  const chunks = [];
  const qa = [];
  const intro = splitProseCode(stripMeta(parts[0].replace(/^#\s+.+$/m, '')));
  if (intro.prose) {
    chunks.push({ tech, text: `${title}. ${intro.prose}`.slice(0, MAX_CHUNK), source: src });
    qa.push({ tech, q: `Mi az a ${title}?`, a: intro.prose.slice(0, MAX_ANSWER) });
  }
  for (const part of parts.slice(1)) {
    const head = part.split('\n', 1)[0].trim();
    const q = meta(part, 'q') || `${head} (${title})`;
    const tags = meta(part, 'tags');
    const { prose, code } = splitProseCode(stripMeta(part.slice(head.length)));
    if (!prose && !code.length) continue;
    const body = [`${title} — ${head}.`, prose, tags ? `Kulcsszavak: ${tags}.` : '', ...code].filter(Boolean).join('\n');
    chunks.push({ tech, text: body.slice(0, MAX_CHUNK), source: `${src}#${head}` });
    const answer = [prose, code[0] ? `\n${code[0]}` : ''].join('').slice(0, MAX_ANSWER);
    qa.push({ tech, q, a: answer });
  }
  return { chunks, qa };
}

const files = ['nyelvek', 'temak'].flatMap((d) => {
  try {
    return readdirSync(join(SRC, d)).filter((f) => f.endsWith('.md')).sort().map((f) => join(SRC, d, f));
  } catch {
    return [];
  }
});
const PB_CHUNKS = [];
const PB_QA = [];
for (const f of files) {
  const r = parseFile(f);
  PB_CHUNKS.push(...r.chunks);
  PB_QA.push(...r.qa);
}
const techs = [...new Set(PB_CHUNKS.map((c) => c.tech))].sort();
const out = `// programmingBrain.ingested.ts — GENERATED by scripts/ingest-programming-brain.mjs from
// Programing_Brain/ (${files.length} files, ${PB_CHUNKS.length} chunks, ${PB_QA.length} Q→A, ${techs.length} techs).
// DO NOT EDIT BY HAND — edit the Markdown in Programing_Brain/ and re-run the script.
export interface PBChunk { tech: string; text: string; source: string }
export interface PBQA { tech: string; q: string; a: string }
export const PB_TECHS: string[] = ${JSON.stringify(techs)};
export const PB_CHUNKS: PBChunk[] = ${JSON.stringify(PB_CHUNKS)};
export const PB_QA: PBQA[] = ${JSON.stringify(PB_QA)};
`;
writeFileSync(OUT, out, 'utf8');
console.log(`programmingBrain: ${files.length} files → ${PB_CHUNKS.length} chunks, ${PB_QA.length} Q→A, ${techs.length} techs, ${(out.length / 1024).toFixed(0)} KB`);
